/**
 * Creates a withdrawal request that locks the requested Winning Coins and schedules them for payout to the specified payout account (bank transfer or UPI). Requires a verified mobile number and accepted Terms & Conditions.
 *
 * Only one active withdrawal (reserved or processing) is permitted per user at a time.
 *
 * Idempotent on the idempotencyKey field — retrying with the same key and same parameters returns the existing withdrawal (200) rather than creating a duplicate.
 *
 * Rate limited: 10 requests per 60 seconds per user.
 * @summary Initiate a withdrawal
 */
export const initiateWithdrawalBodyAmountMin = 100;

export const initiateWithdrawalBodyIdempotencyKeyMax = 128;



export const InitiateWithdrawalBody = zod.object({
  "amount": zod.number().min(initiateWithdrawalBodyAmountMin).describe('Winning Coins to withdraw. Must be a whole number >= 100 (₹100 minimum).\n'),
  "payoutAccountId": zod.string().uuid().describe('ID of a pre-registered, non-deleted payout account (bank transfer or UPI) belonging to the authenticated user.\n'),
  "idempotencyKey": zod.string().min(1).max(initiateWithdrawalBodyIdempotencyKeyMax).describe('Client-generated key. Retrying with the same key and the same amount + payoutAccountId returns the existing withdrawal without creating a duplicate. Retrying with the same key but different parameters returns 409.\n')
})

